// Phase 1: Pick only the first India query (1 city) for the initial test run.
// In Phase 2, change this to loop all 30 India queries.
const data = $input.first().json;
const indiaQueries = data.india || [];

// For Phase 1: take just the first query
const selected = indiaQueries.slice(0, 1);

return selected.map(q => ({
  json: {
    query: q.niche,
    location: q.city,
    country: q.country,
    region: 'india',
    max_results: 10  // Phase 1: 10 per query. Increase to 30 in Phase 2.
  }
}));

// Flatten the leads array from the scraper response into individual items.
const response = $input.first().json;
const leads = response.leads || [];

if (!leads.length) {
  console.log('No leads returned from scraper.');
  return [];
}

console.log(`Received ${leads.length} leads from scraper.`);
return leads.map(lead => ({ json: lead }));

// Build the pain-point detection prompt
const lead = $('flatten-leads').first().json;
const leadId = $input.first().json[0]?.id;

const systemPrompt = `You are a B2B sales researcher for VoxAI Agents, a company that builds AI-powered WhatsApp agents, Voice AI agents, and business automation systems for other businesses.

Analyze the following business and identify:
1. Their most likely customer-communication pain point.
2. The single most compelling, specific angle to open a cold outreach conversation.

Important regional context:
- india: WhatsApp is the primary business channel; manual handling of enquiries is common.
- AE/QA/SA (Gulf): Higher-value transactions; WhatsApp widely used; owners are decision-makers.
- SG: English-first, efficiency matters, quality of customer service is key.
Do NOT mix regional assumptions across countries.

Respond ONLY in this JSON format, no preamble:
{
  "pain_point": "short description (max 20 words)",
  "angle": "specific opening angle referencing something concrete (max 40 words)",
  "confidence": "high | medium | low"
}`;

const userContent = `Business details:
- Name: ${lead.business_name}
- Category: ${lead.category || 'Unknown'}
- Region: ${lead.region} (${lead.country})
- Has website: ${lead.has_website}
- Website content: ${lead.website_text_excerpt || 'N/A'}
- Running ads: ${lead.is_running_ads || false}
- Ad copy: ${lead.ad_copy || 'N/A'}
- Rating/reviews: ${lead.rating || 'N/A'} (${lead.review_count || 0} reviews)`;

return [{
  json: {
    lead_id: leadId,
    lead: lead,
    system_prompt: systemPrompt,
    user_content: userContent
  }
}];

// Parse Groq response for pain-point (OpenAI format: choices[0].message.content)
const response = $input.first().json;
const rawText = response.choices?.[0]?.message?.content || '{}';

let parsed = {};
try {
  const cleaned = rawText.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  console.error('Failed to parse Groq pain-point response:', rawText);
  parsed = { pain_point: 'Unable to determine', angle: 'Unable to determine', confidence: 'low' };
}

const prev = $('build-pain-point-prompt').first().json;
return [{ json: { ...prev, pain_point: parsed.pain_point || '', angle: parsed.angle || '', confidence: parsed.confidence || 'low' } }];

// Build the WhatsApp message drafting prompt
const data = $input.first().json;
const lead = data.lead;

const toneMap = {
  IN: "Casual, Hinglish-friendly where natural — like messaging a fellow business owner on WhatsApp, not writing a formal email. Keep it warm and direct.",
  AE: "Professional English, respectful and direct. No slang. Gulf business culture values formality and clarity. Keep it crisp.",
  QA: "Professional English, respectful and direct. No slang. Gulf business culture values formality and clarity. Keep it crisp.",
  SA: "Professional English, respectful and direct. No slang. Saudi business culture values relationship and trust. Be polite and clear.",
  SG: "Professional English, concise and efficiency-focused. Singapore SMEs value speed and directness. Get to the point fast."
};
const tone = toneMap[lead.country] || "Professional English.";

const systemPrompt = `Write a short, casual, first-touch WhatsApp outreach message to a business owner.

Rules:
- Under 400 characters total.
- Do NOT open with "Hi, we offer..." or any generic pitch.
- Do NOT mention "AI" or "automation" explicitly — focus on the pain point and outcome.
- Open with something specific referencing their business (use the angle below).
- Ask one question at the end — the goal is a reply, not a sale.
- Tone: ${tone}
- Max 1 emoji (optional). No excessive punctuation.
- Do not sign off with a company name or website link.

Output ONLY the message text. No quotes, no preamble.`;

const userContent = `Business: ${lead.business_name} (${lead.category}, ${lead.region}, ${lead.country})
Pain point: ${data.pain_point}
Angle: ${data.angle}`;

return [{
  json: {
    ...data,
    wa_system_prompt: systemPrompt,
    wa_user_content: userContent
  }
}];

// Parse Groq WA draft response (OpenAI format) and build wa.me deep link
const response = $input.first().json;
const waDraft = (response.choices?.[0]?.message?.content || '').trim();

const prev = $('build-wa-draft-prompt').first().json;
const lead = prev.lead;

let waDeepLink = null;
if (lead.phone_normalized) {
  const numericPhone = lead.phone_normalized.replace('+', '');
  waDeepLink = `https://wa.me/${numericPhone}?text=${encodeURIComponent(waDraft)}`;
}

return [{ json: {
  lead_id: prev.lead_id,
  pain_point: prev.pain_point,
  angle: prev.angle,
  confidence: prev.confidence,
  whatsapp_draft: waDraft,
  whatsapp_deep_link: waDeepLink,
  low_confidence_flag: prev.confidence === 'low'
} }];
